import assert from "node:assert/strict";
import { test } from "node:test";
import { sortBy } from "../src/sort.ts";

test("grader: sortBy", () => {
  const input = [{ k: 2, i: 0 }, { k: 1, i: 1 }, { k: 2, i: 2 }];
  const r = sortBy(input, (x) => x.k);
  assert.deepEqual(r.map((x) => x.i), [1, 0, 2]);
  assert.deepEqual(input.map((x) => x.i), [0, 1, 2]);
  assert.deepEqual(sortBy(["b", "a", "c"], (s) => s), ["a", "b", "c"]);
});

