// sorting helpers

export function sortBy<T>(items: readonly T[], keyOf: (item: T) => number | string): T[] {
  return items
    .map((item, index) => ({ item, index, key: keyOf(item) }))
    .sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : a.index - b.index))
    .map((e) => e.item);
}

