// sorting helpers

export function sortBy<T>(items: T[], keyOf: (item: T) => number | string): T[] {
  return items.sort((a, b) => {
    const ka = keyOf(a);
    const kb = keyOf(b);
    return ka < kb ? -1 : ka > kb ? 1 : 0;
  });
}
